def phi(n):
    res = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            res -= res // p
        p += 1
    if temp > 1:
        res -= res // temp
    return res

print(phi(2013))

def L(a, b):
    if a == 1 and b == 0: return 0
    if a == 0 and b == 1: return 0
    if a > b: return 1 + L(a - b, b)
    if b > a: return 1 + L(a, b - a)

max_L = 0
for S in range(2, 2014):
    for b in range(1, S):
        import math
        if math.gcd(S - b, b) == 1:
            max_L = max(max_L, L(S - b, b))
print(max_L)
